    return dict(schema_version=BUNDLE_VERSION, spec_version=SPEC_VERSION, subject_id="fixture-person",
                captured_at="2026-09-07T10:00:00+08:00", capture_profile="consumer",
                roi_version="roi-v3", scale_version="aligned-1024", calibration_version="uncalibrated",
                modules=[{"id": m.id} for m in MODULES],
                measurements=[measurement("01", "density", "full_face", "consumer", 10)],
                media=[])

def test_registry_weights_and_regions():
    assert len(MODULES) == 11
    for m in MODULES:
        assert sum(m.weights.values()) == pytest.approx(1)
        assert len(set(m.regions)) == len(m.regions)
    assert "left_inner_cheek" in MODULES[0].regions
    assert "forehead" in MODULES[4].regions

@pytest.mark.parametrize("raw,shown,label", [(20.49,20,"显著"), (20.5,21,"较明显"),(40.5,41,"中度"),(60.5,61,"轻度"),(80.5,81,"未见明显"),(100,100,"未见明显")])
def test_round_once(raw, shown, label):
    assert display_score(raw) == shown
    assert grade(raw) == label

def test_uncalibrated_is_not_a_score():
    m = sample()["measurements"][0]
    assert score_metric(m)["score"] is None
    assert score_metric({**m, "status": "unavailable", "value": None})["status"] == "unavailable"

def test_ecdf_direction_and_profile_isolation():
    m = sample()["measurements"][0]
    ref = {**m, "version": "test-only", "population_sha256": "a"*64, "sorted_values": [0, 5, 10, 15, 20]}
    assert score_metric(m, ref)["score"] == 50
    assert score_metric({**m,"value": 20}, ref)["score"] < score_metric(m, ref)["score"]
    with pytest.raises(ValueError):
        score_metric({**m, "capture_profile": "institution"}, ref)
    assert aggregate({"a": {"score_raw": None}}, {"a": 1})["score"] is None

def test_history_gates():
    now = sample()
    old = copy.deepcopy(now)
    old["captured_at"] = "2026-09-06T10:00:00+08:00"
    old["measurements"][0]["value"] = 12
    assert compare(now)["status"] == "no_history"
    assert compare(now, old)["items"][0]["delta"] == -2
    assert "改善" not in json.dumps(compare(now, old), ensure_ascii=False)
    old["capture_profile"] = "institution"
    assert compare(now, old)["items"][0]["delta"] is None
    old["subject_id"] = "other"
    with pytest.raises(ValueError):
        compare(now, old)

def test_bundle_relocation_and_tamper(tmp_path):
    root = publish(tmp_path / "bundle", sample(), {})
    moved = tmp_path / "moved"
    root.rename(moved)
    assert load(moved)["subject_id"] == "fixture-person"
    (moved / "report.json").write_text("{}", encoding="utf-8")
